package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_pow_TriageGen2Test {

    private static final double DELTA = 1e-15;





    @Test
    public void testPow_ZeroBase() {
        assertEquals(0.0, FastMath.pow(0.0, 5.0), DELTA);
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(0.0, -2.0), DELTA);

        // Negative zero cases
        double negZero = -0.0;
        // y is odd integer: -0.0 ^ 3 = -0.0
        assertEquals(-0.0, FastMath.pow(negZero, 3.0), DELTA);
        // y is odd integer: -0.0 ^ -3 = -inf
        assertEquals(Double.NEGATIVE_INFINITY, FastMath.pow(negZero, -3.0), DELTA);
        // y is even integer: -0.0 ^ 2 = -0.0 (based on code logic: if (y > 0 && y == yi && (yi & 1) == 1) return -0.0)
        // Note: the code specifically checks if (yi & 1) == 1 (odd) for both cases.
        assertEquals(-0.0, FastMath.pow(negZero, 2.0), DELTA); // This follows the code's specific if-logic
    }










}

package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_pow_TriageGen2Test {

    private static final double DELTA = 1e-15;







    @Test
    public void testPow_InfinityBase() {
        assertEquals(0.0, FastMath.pow(Double.POSITIVE_INFINITY, -1.0), DELTA);
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(Double.POSITIVE_INFINITY, 2.0), DELTA);

        // y is NaN for PosInf
        assertTrue(Double.isNaN(FastMath.pow(Double.POSITIVE_INFINITY, Double.NaN)));

        // y is Infinity
        assertTrue(Double.isNaN(FastMath.pow(1.0, Double.POSITIVE_INFINITY)));
        assertTrue(Double.isNaN(FastMath.pow(-1.0, Double.POSITIVE_INFINITY)));
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(2.0, Double.POSITIVE_INFINITY), DELTA);
        assertEquals(0.0, FastMath.pow(0.5, Double.POSITIVE_INFINITY), DELTA);

        // y is Negative Infinity
        assertTrue(Double.isNaN(FastMath.pow(1.0, Double.NEGATIVE_INFINITY)));
        assertTrue(Double.isNaN(FastMath.pow(-1.0, Double.NEGATIVE_INFINITY)));
        assertEquals(0.0, FastMath.pow(2.0, Double.NEGATIVE_INFINITY), DELTA);
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(0.5, Double.NEGATIVE_INFINITY), DELTA);
    }








}

package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_pow_TriageGen2Test {

    private static final double DELTA = 1e-15;









    @Test
    public void testPow_NegativeInfinityBase() {
        // y is NaN
        assertTrue(Double.isNaN(FastMath.pow(Double.NEGATIVE_INFINITY, Double.NaN)));

        // y < 0
        // y is odd integer: -inf ^ -3 = -0.0 (based on code logic)
        assertEquals(-0.0, FastMath.pow(Double.NEGATIVE_INFINITY, -3.0), DELTA);
        // y is even integer: -inf ^ -2 = 0.0
        assertEquals(0.0, FastMath.pow(Double.NEGATIVE_INFINITY, -2.0), DELTA);
        // y is not integer: -inf ^ -2.5 = 0.0
        assertEquals(0.0, FastMath.pow(Double.NEGATIVE_INFINITY, -2.5), DELTA);

        // y > 0
        // y is odd integer: -inf ^ 3 = -inf
        assertEquals(Double.NEGATIVE_INFINITY, FastMath.pow(Double.NEGATIVE_INFINITY, 3.0), DELTA);
        // y is even integer: -inf ^ 2 = inf
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(Double.NEGATIVE_INFINITY, 2.0), DELTA);
        // y is not integer: -inf ^ 2.5 = inf
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(Double.NEGATIVE_INFINITY, 2.5), DELTA);
    }






}

