package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_pow_TriageGen2Test {

    private static final double DELTA = 1e-15;













    @Test
    public void testPow_LargeY() {
        // Testing the 'else' branch for y split (y > 8e298 or y < -8e298)
        double hugeY = 1e300;
        // We don't necessarily check exact value due to precision, but ensure it runs
        double res = FastMath.pow(1.1, hugeY);
        assertTrue(Double.isInfinite(res) || res > 0);

        double hugeNegY = -1e300;
        double resNeg = FastMath.pow(1.1, hugeNegY);
        assertEquals(0.0, resNeg, DELTA);
    }


}

package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_pow_TriageGen2Test {

    private static final double DELTA = 1e-15;















    @Test
    public void testPow_EdgeCases() {
        // x*x == 1.0 case for y = Infinity
        assertTrue(Double.isNaN(FastMath.pow(1.0, Double.POSITIVE_INFINITY)));
        assertTrue(Double.isNaN(FastMath.pow(-1.0, Double.POSITIVE_INFINITY)));

        // x*x == 1.0 case for y = -Infinity
        assertTrue(Double.isNaN(FastMath.pow(1.0, Double.NEGATIVE_INFINITY)));
        assertTrue(Double.isNaN(FastMath.pow(-1.0, Double.NEGATIVE_INFINITY)));

        // x*x < 1.0 case for y = -Infinity
        assertEquals(Double.POSITIVE_INFINITY, FastMath.pow(0.5, Double.NEGATIVE_INFINITY), DELTA);

        // x*x > 1.0 case for y = -Infinity
        assertEquals(0.0, FastMath.pow(2.0, Double.NEGATIVE_INFINITY), DELTA);
    }
}
